#include <iostream>
#include <vector>
#include <string>
#include <vector>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    long long n;
    long long m;
    cin >> n >> m;
    vector<long long> a(n);
    for (int i = 0; i < n; i++) cin >> a[i];
    vector<long long> pat(m);
    for (int i = 0; i < m; i++) cin >> pat[i];

    int cn = (int)n, cm = (int)m;
    vector<int> d(cn - 1);
    for (int i = 0; i + 1 < cn; i++) d[i] = (a[i + 1] > a[i]) - (a[i + 1] < a[i]);
    vector<int> pi(cm, 0);
    for (int i = 1; i < cm; i++) {
        int k = pi[i - 1];
        while (k > 0 && pat[i] != pat[k]) k = pi[k - 1];
        if (pat[i] == pat[k]) k++;
        pi[i] = k;
    }
    int k = 0;
    long long count = 0;
    for (int x : d) {
        while (k > 0 && pat[k] != x) k = pi[k - 1];
        if (pat[k] == x) k++;
        if (k == cm) {
            count++;
            k = pi[k - 1];
        }
    }
    cout << count << "\n";

    return 0;
}

