import java.io.*;
import java.util.*;

public class Main {
    static BufferedReader in = new BufferedReader(new InputStreamReader(System.in));
    static StringTokenizer tokens = new StringTokenizer("");

    static String next() throws IOException {
        while (!tokens.hasMoreTokens()) {
            tokens = new StringTokenizer(in.readLine());
        }
        return tokens.nextToken();
    }

    public static void main(String[] args) throws IOException {
        long n = Long.parseLong(next());
        long m = Long.parseLong(next());
        long[] a = new long[(int) n];
        for (int i = 0; i < a.length; i++) a[i] = Long.parseLong(next());
        long[] pat = new long[(int) m];
        for (int i = 0; i < pat.length; i++) pat[i] = Long.parseLong(next());

        int cn = (int) n, cm = (int) m;
        int[] d = new int[cn - 1];
        for (int i = 0; i + 1 < cn; i++) d[i] = Long.compare(a[i + 1], a[i]);
        int[] pi = new int[cm];
        for (int i = 1; i < cm; i++) {
            int k = pi[i - 1];
            while (k > 0 && pat[i] != pat[k]) k = pi[k - 1];
            if (pat[i] == pat[k]) k++;
            pi[i] = k;
        }
        int k = 0;
        long count = 0;
        for (int x : d) {
            while (k > 0 && pat[k] != x) k = pi[k - 1];
            if (pat[k] == x) k++;
            if (k == cm) {
                count++;
                k = pi[k - 1];
            }
        }
        System.out.println(count);
    }
}
